examples.template:
MonarchButton({{trigger}}, variant: .danger) { isConfirming = true }
    .sheet(isPresented: $isConfirming) {
        MonarchStepUpAuthDialog(
            description: {{description}},
            methods: [.password],
            onForgot: {},
            onCancel: { isConfirming = false },
            onVerified: {
                isConfirming = false
            },
            onVerify: { credential in
                // Send the credential to the server; throw if it is refused.
                try await Task.sleep(for: .milliseconds(300))
            }
        )
    }

